class Solution {
    public boolean checkRecord(String s) {
        int absences = 0, consecutiveLate = 0;
        for (char c : s.toCharArray()) {
            if (c == 'A') {
                absences++;
                if (absences >= 2) return false;
                consecutiveLate = 0;
            } else if (c == 'L') {
                consecutiveLate++;
                if (consecutiveLate >= 3) return false;
            } else {
                consecutiveLate = 0;
            }
        }
        return true;
    }
}
